// Publicatie-gating (drip): een artikel is pas zichtbaar zodra zijn datum bereikt is.
export function isPublished(slug: string, now: Date = new Date()): boolean {
  const d = GUIDE_META[slug]?.date
  return d ? new Date(d).getTime() <= now.getTime() : true
}

// Gepubliceerde slugs in GUIDE_ORDER-volgorde (nieuwste eerst gebeurt in de pagina via datum-sortering).
export function publishedSlugs(now: Date = new Date()): string[] {
  return GUIDE_ORDER.filter((s) => GUIDES[s] && isPublished(s, now))
}
